import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { smoothKeepingCorners } from "../render/corner-smoothing";
import {
  freedrawPath,
  getFreeDrawSvgPath,
  inkFreedrawPath,
  isSimulatedPressure,
  type FreedrawElement,
} from "../render/excalidraw-freedraw";

// Generated by running Excalidraw v0.18.1's own getFreeDrawSvgPath (renderElement.ts,
// verbatim) on this fixed point set, with perfect-freehand 1.2.3. The repo is
// pinned to 1.2.0, which reproduces this golden exactly, so it is not regenerated.
type Golden = { points: number[][]; out: Record<string, string> };
const g = JSON.parse(
  readFileSync(new URL("./fixtures/excalidraw-freedraw.golden.json", import.meta.url), "utf8"),
) as Golden;

function element(over: Partial<FreedrawElement>): FreedrawElement {
  return {
    points: g.points,
    pressures: g.points.map(() => 0.5),
    strokeWidth: 4,
    simulatePressure: true,
    lastCommittedPoint: [0, 0],
    ...over,
  };
}

test("matches Excalidraw output for a sparse arc, mouse pressure, width 2", () => {
  assert.equal(getFreeDrawSvgPath(element({ strokeWidth: 2 })), g.out.sparseArcMouse);
});

test("matches Excalidraw output at width 4 (the default pen)", () => {
  assert.equal(getFreeDrawSvgPath(element({ strokeWidth: 4 })), g.out.sparseArcMouse4);
});

test("matches Excalidraw output for real pen pressure (simulatePressure false)", () => {
  const pressures = g.points.map((_, i) => 0.2 + (i / 30) * 0.6);
  assert.equal(
    getFreeDrawSvgPath(element({ strokeWidth: 8, simulatePressure: false, pressures })),
    g.out.penPressure8,
  );
});

test("matches Excalidraw output for a single point", () => {
  assert.equal(
    getFreeDrawSvgPath(element({ points: [[5, 5]], pressures: [0.5], strokeWidth: 2 })),
    g.out.dotOne,
  );
});

test("matches Excalidraw output while the stroke is still wet (no lastCommittedPoint)", () => {
  assert.equal(getFreeDrawSvgPath(element({ lastCommittedPoint: null })), g.out.wetNoLast);
});

test("is a closed quadratic path: Q segments, one closing L, then Z", () => {
  const d = getFreeDrawSvgPath(element({}));
  assert.ok(d.startsWith("M"));
  assert.ok(d.endsWith("Z"));
  assert.equal(d.match(/ L /g)?.length, 1);
  assert.ok(d.includes(" Q"));
});

test("gives finite numbers at the two smallest pen sizes", () => {
  for (const width of [2, 4]) {
    const d = getFreeDrawSvgPath(element({ strokeWidth: width }));
    assert.doesNotMatch(d, /NaN|Infinity/);
    assert.ok(d.length > 100);
  }
});

// Paper ink: `freedrawPath` takes the stored pressure bytes (0-255).

const PX = [0, 40, 90, 150, 220];
const PY = [0, 20, 10, 40, 30];

test("paper freehand with mid pressure, or none, is the mouse path", () => {
  const none = freedrawPath(PX, PY, 6, true);
  assert.equal(freedrawPath(PX, PY, 6, true, [128, 128, 128, 128, 128]), none);
  assert.equal(freedrawPath(PX, PY, 6, true, [127, 128, 128, 128, 128]), none);
  // A pressure list that does not match the points is treated as missing.
  assert.equal(freedrawPath(PX, PY, 6, true, [230, 230]), none);
});

test("paper freehand with real pressure draws the pen path from that pressure", () => {
  const bytes = [60, 120, 200, 240, 90];
  const d = freedrawPath(PX, PY, 6, true, bytes);
  assert.notEqual(d, freedrawPath(PX, PY, 6, true));
  assert.equal(
    d,
    inkFreedrawPath(
      PX.map((x, i) => [x, PY[i]!]),
      bytes.map((b) => b / 255),
      6,
      false,
      true,
    ),
  );
});

test("pressure is real once any sample leaves the midpoint, not only the first", () => {
  assert.equal(isSimulatedPressure([]), true);
  assert.equal(isSimulatedPressure([0.5, 0.5, 0.5]), true);
  assert.equal(isSimulatedPressure([128 / 255, 0.5]), true);
  assert.equal(isSimulatedPressure([0.5, 0.5, 0.8]), false);
  assert.equal(isSimulatedPressure([0.2]), false);
});

// A "V" whose corner sits at y = 100, sampled every 5 units like a quick pen stroke.
const V: number[][] = [
  ...Array.from({ length: 21 }, (_, i) => [i * 2.5, i * 5]),
  ...Array.from({ length: 20 }, (_, i) => [52.5 + i * 2.5, 95 - i * 5]),
];

function lowestY(d: string): number {
  const nums = d.match(/-?\d+(?:\.\d+)?/g)!.map(Number);
  return Math.max(...nums.filter((_, i) => i % 2 === 1));
}

test("the default ink reaches a sharp corner instead of rounding it off, mouse and pen", () => {
  for (const simulatePressure of [true, false]) {
    for (const width of [1, 2, 4]) {
      const d = inkFreedrawPath(V, V.map(() => 0.6), width, simulatePressure, true);
      assert.ok(lowestY(d) > 99.5, `width ${width}, ${simulatePressure ? "mouse" : "pen"}: tip at ${lowestY(d)}`);
    }
  }
});

/** A circle of radius 40 about (50, 50), each sample nudged by up to `noise` units like a shaky hand. */
function shakyCircle(noise: number): number[][] {
  let seed = 7;
  const jitter = () => ((seed = (seed * 16807) % 2147483647) / 2147483647 - 0.5) * 2 * noise;
  return Array.from({ length: 121 }, (_, i) => {
    const a = (i / 120) * 2 * Math.PI;
    return [50 + 40 * Math.cos(a) + jitter(), 50 + 40 * Math.sin(a) + jitter()];
  });
}

/** How much the outer edge's distance from the centre wanders: 0 for a true circle. */
function wobble(d: string): number {
  const nums = d.match(/-?\d+(?:\.\d+)?/g)!.map(Number);
  const radii: number[] = [];
  for (let i = 0; i + 1 < nums.length; i += 2) {
    const r = Math.hypot(nums[i]! - 50, nums[i + 1]! - 50);
    if (r > 40) radii.push(r);
  }
  const mean = radii.reduce((a, b) => a + b, 0) / radii.length;
  return Math.sqrt(radii.reduce((a, r) => a + (r - mean) ** 2, 0) / radii.length);
}

test("a shaky circle wobbles less with the default ink than with the old raw points at streamline 0.5", () => {
  const old = { thinning: 0, smoothing: 0.5, streamline: 0.5, size: 2 * 1.35 };
  for (const noise of [0.5, 1]) {
    const pts = shakyCircle(noise);
    const press = pts.map(() => 0.5);
    const now = wobble(inkFreedrawPath(pts, press, 2, true, true));
    const raw = { points: pts, pressures: press, strokeWidth: 0, simulatePressure: true, lastCommittedPoint: [0, 0] };
    const before = wobble(getFreeDrawSvgPath(raw as FreedrawElement, old));
    assert.ok(now < before, `noise ${noise}: wobble ${now} vs ${before} before`);
  }
});

test("smoothing keeps a corner point and both ends where they were drawn", () => {
  const out = smoothKeepingCorners(V);
  assert.equal(out.length, V.length);
  assert.deepEqual(out[0], V[0]);
  assert.deepEqual(out[20], V[20]);
  assert.deepEqual(out.at(-1), V.at(-1));
  assert.deepEqual(smoothKeepingCorners([[0, 0], [1, 1]]), [[0, 0], [1, 1]]);
});
